#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> localBins{};
        localBins.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Values are specified to be in [0, 100], inclusive.
            // Put 100 into the last bin [90, 100].
            int idx = static_cast<int>(v / 10.0);
            if (idx < 0) idx = 0;
            if (idx > 9) idx = 9;

            ++localBins[static_cast<std::size_t>(idx)];
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += localBins[b];
            }
        }
    }
}
